-- Content, shipped as a migration (decision 0019): the phrase and Internet Archive copy for each
-- claim source, approved by the owner on 29 Oct 2026 (issue #127, claims policy decision 0005).
-- A phrase is a short verbatim quote from the public page that supports the claim; the weekly
-- source link checker looks for it. HBK's release notes answer 403 to bots, so it has an archive
-- copy and no phrase. No broken day is set anywhere, and nothing on the site shows these yet.
-- Some archive copies are of a redirect target, not the stored URL: BusinessPost moved to /banking/,
-- and Triple-A and Techzim are on their www hosts. Each was read and shows the claim.
-- Safe to run again, and a no-op where the stop or the URL is absent: every statement is keyed by
-- the stop slug and the exact source URL. supabase/seed.sql holds the same statements.

update public.outcomes set source_phrase = '1M+ Downloads', source_archive_url = 'https://web.archive.org/web/20260825091438/https://play.google.com/store/apps/details?id=com.accessbankplc.quickbucks' where source_url = 'https://play.google.com/store/apps/details?id=com.accessbankplc.quickbucks' and stop_id = (select id from public.stops where slug = 'access-bank');
update public.outcomes set source_phrase = 'over 90 BNPLs and local payment methods in over 120 countries', source_archive_url = 'https://web.archive.org/web/20260306171201/https://www.triple-a.io/newsroom/optty-partners-with-triple-a-to-expand-payment-architectures-into-digital-currencies' where source_url = 'https://triple-a.io/newsroom/optty-partners-with-triple-a-to-expand-payment-architectures-into-digital-currencies' and stop_id = (select id from public.stops where slug = 'optty');
update public.outcomes set source_phrase = 'the client saved 11% or over $500,000 in annual fuel costs from just several hundred sites', source_archive_url = 'https://web.archive.org/web/20260614064147/https://galooli.com/case-studies/deep-dive-into-remote-site-energy-use/' where source_url = 'https://galooli.com/case-studies/deep-dive-into-remote-site-energy-use/' and stop_id = (select id from public.stops where slug = 'galooli');
update public.outcomes set source_phrase = 'serving over 17 million customers across Africa, Asia, and Europe', source_archive_url = 'https://web.archive.org/web/20250418013723/https://www.techzim.co.zw/2025/03/20years-mukuru-milestones-that-shaped-journey/' where source_url = 'https://techzim.co.zw/2025/03/20years-mukuru-milestones-that-shaped-journey' and stop_id = (select id from public.stops where slug = 'mukuru');
update public.outcomes set source_archive_url = 'https://web.archive.org/web/20260218002429/https://www.hbkworld.com/en/products/support-resources/release-notes/advantage-insights' where source_url = 'https://www.hbkworld.com/en/products/support-resources/release-notes/advantage-insights' and stop_id = (select id from public.stops where slug = 'hbk');
update public.stops set detail_sources = (select jsonb_agg(case when item->>'url' = 'https://businesspost.ng/2019/08/14/access-bank-boosts-lending-with-smartphone-device-financing-scheme/' then item || jsonb_build_object('phrase', 'designed to provide salaried customers with the opportunity to purchase smartphones of their choice and pay over a period of 12 months', 'archive_url', 'https://web.archive.org/web/20261029222411/https://businesspost.ng/banking/access-bank-boosts-lending-with-smartphone-device-financing-scheme/') else item end order by ord) from jsonb_array_elements(detail_sources) with ordinality as t(item, ord)) where slug = 'access-bank' and detail_sources @> '[{"url": "https://businesspost.ng/2019/08/14/access-bank-boosts-lending-with-smartphone-device-financing-scheme/"}]'::jsonb;
update public.stops set detail_sources = (select jsonb_agg(case when item->>'url' = 'https://brandcom.ng/2023/05/24/access-bank-konga-partner-to-provide-installment-payments-through-pay-with-quickbucks/' then item || jsonb_build_object('phrase', 'partnered to offer installment payments to customers through Pay with QuickBucks', 'archive_url', 'https://web.archive.org/web/20261029213726/https://brandcom.ng/2023/05/24/access-bank-konga-partner-to-provide-installment-payments-through-pay-with-quickbucks/') else item end order by ord) from jsonb_array_elements(detail_sources) with ordinality as t(item, ord)) where slug = 'access-bank' and detail_sources @> '[{"url": "https://brandcom.ng/2023/05/24/access-bank-konga-partner-to-provide-installment-payments-through-pay-with-quickbucks/"}]'::jsonb;
